python3 -c "
from pypdf import PdfReader
reader = PdfReader('/root/sc100-filled.pdf')
for i, page in enumerate(reader.pages):
    print(f'--- Page {i+1} ---')
    if '/Annots' in page:
        for annot in page['/Annots']:
            obj = annot.get_object()
            if obj.get('/T'):
                v = obj.get('/V')
                if v:
                    print(f'{obj[\"/T\"]}: {v}')
"
